effect.shader:
const float PI = 3.14159265;

float hash3(vec3 p) {
    p = fract(p * vec3(0.1031, 0.1030, 0.0973));
    p += dot(p, p.yxz + 33.33);
    return fract((p.x + p.y) * p.z);
}

float vnoise(vec3 p) {
    vec3 i = floor(p);
    vec3 f = fract(p);
    vec3 s = f * f * (3.0 - 2.0 * f);
    float a = hash3(i);
    float b = hash3(i + vec3(1.0, 0.0, 0.0));
    float c = hash3(i + vec3(0.0, 1.0, 0.0));
    float d = hash3(i + vec3(1.0, 1.0, 0.0));
    float e = hash3(i + vec3(0.0, 0.0, 1.0));
    float g = hash3(i + vec3(1.0, 0.0, 1.0));
    float h = hash3(i + vec3(0.0, 1.0, 1.0));
    float k = hash3(i + vec3(1.0, 1.0, 1.0));
    return mix(mix(mix(a, b, s.x), mix(c, d, s.x), s.y),
               mix(mix(e, g, s.x), mix(h, k, s.x), s.y), s.z);
}

float worley(vec3 p) {
    vec3 i = floor(p);
    vec3 f = fract(p);
    float m = 1.0;
    for (int z = -1; z <= 1; z++) {
        for (int y = -1; y <= 1; y++) {
            for (int x = -1; x <= 1; x++) {
                vec3 c = vec3(float(x), float(y), float(z));
                vec3 o = vec3(hash3(i + c), hash3(i + c + 17.1), hash3(i + c + 31.7));
                m = min(m, length(c + o - f));
            }
        }
    }
    return 1.0 - clamp(m, 0.0, 1.0);
}

vec3 girar(vec3 p, vec3 a) {
    float cx = cos(a.x); float sx = sin(a.x);
    float cy = cos(a.y); float sy = sin(a.y);
    float cz = cos(a.z); float sz = sin(a.z);
    p = vec3(p.x, cx * p.y - sx * p.z, sx * p.y + cx * p.z);
    p = vec3(cy * p.x + sy * p.z, p.y, -sy * p.x + cy * p.z);
    p = vec3(cz * p.x - sz * p.y, sz * p.x + cz * p.y, p.z);
    return p;
}

/** Um noise do painel: tipo, complexidade (oitavas) e evolucao (anda no 4o eixo). */
float noiseTipo(vec3 p, float tipo, float cx, float evo) {
    int t = int(tipo + 0.5);
    int n = clamp(int(cx + 0.5), 1, 8);
    if (t == 1) {
        // Spiral: o espaco gira em torno de Y conforme o raio
        float r = length(p.xz);
        float ang = r * 0.7 + evo * 0.15;
        p.xz = vec2(cos(ang) * p.x - sin(ang) * p.z, sin(ang) * p.x + cos(ang) * p.z);
    }
    float soma = 0.0;
    float peso = 0.0;
    float amp = 1.0;
    vec3 q = p + vec3(evo * 0.11, evo * 0.07, evo * 0.13);
    for (int i = 0; i < 8; i++) {
        if (i >= n) break;
        float v;
        if (t == 2) v = worley(q);
        else if (t == 3) v = 1.0 - abs(vnoise(q) * 2.0 - 1.0);
        else v = vnoise(q);
        soma += v * amp;
        peso += amp;
        amp *= 0.5;
        q = q * 2.02 + vec3(3.1, 7.7, 1.3);
    }
    float r = soma / max(peso, 1e-4);
    if (t == 3) r = r * r;
    return r;
}

/** Densidade do noise i com Offset/Contrast/Scale/Evolution/Limit como no painel. */
float umNoise(vec3 p, float tipo, float cx, float off, float con, float sc, vec3 sxyz, vec3 o, float evo, float lim) {
    vec3 q = (p + o) / (max(sc, 1.0) * 0.01 * max(sxyz * 0.01, vec3(0.01)) * 300.0);
    float v = noiseTipo(q, tipo, cx, evo);
    v = (v - 0.5) * (con * 0.01) + 0.5 + off * 0.1;
    if (lim > 0.5) v = min(v, 1.0);
    return v;
}

float aplica(float d, float v, float op) {
    int o = int(op + 0.5);
    if (o == 1) return d - v;
    if (o == 2) return d * v;
    return d + v;
}

/** Rampa de feather: 1 dentro, cai ate 0 na borda (Density Feather Ramp). */
float pena(float x) {
    return 1.0 - smoothstep(featherStart, max(featherEnd, featherStart + 1e-3), x);
}

float densidade(vec3 p, vec3 lp) {
    float borda;
    if (int(shape + 0.5) == 1) {
        borda = length(lp) / max(diameter * 0.5, 1.0);
    } else {
        vec3 h = vec3(width, height, depth) * 0.5;
        vec3 a = abs(lp) / max(h, vec3(1.0));
        borda = max(a.x, max(a.y, a.z));
    }
    if (borda >= 1.0) return 0.0;
    float d = density * 0.05;
    if (n1On > 0.5) d = aplica(d, umNoise(lp, n1Type, n1Cx, n1Off, n1Con, n1Sc, vec3(n1SX, n1SY, n1SZ), vec3(n1OX, n1OY, n1OZ), n1Evo, n1Lim), n1Op);
    if (n2On > 0.5) d = aplica(d, umNoise(lp, n2Type, n2Cx, n2Off, n2Con, n2Sc, vec3(n2SX, n2SY, n2SZ), vec3(n2OX, n2OY, n2OZ), n2Evo, n2Lim), n2Op);
    if (n3On > 0.5) d = aplica(d, umNoise(lp, n3Type, n3Cx, n3Off, n3Con, n3Sc, vec3(n3SX, n3SY, n3SZ), vec3(n3OX, n3OY, n3OZ), n3Evo, n3Lim), n3Op);
    d = max(d, 0.0) * pena(borda);
    return d * densFactor;
}

vec3 posEstrela(int i) {
    float s = float(i) * 13.17 + starsSeed * 3.71;
    vec3 r = vec3(hash3(vec3(s, 1.0, 2.0)), hash3(vec3(3.0, s, 4.0)), hash3(vec3(5.0, 6.0, s))) - 0.5;
    if (int(shape + 0.5) == 1) return r * diameter * 0.8;
    return r * vec3(width, height, depth) * 0.8;
}

vec3 emissao(float d, vec3 lp, vec2 uv) {
    int src = int(emissionSource + 0.5);
    vec3 c = emissionColor.rgb;
    if (src == 1) {
        float x;
        int b = int(gradBase + 0.5);
        float esc = max(gradScale, 1.0) * 0.01;
        if (b == 1) {
            float raio = int(shape + 0.5) == 1 ? diameter * 0.5 : max(width, max(height, depth)) * 0.5;
            x = length(lp) / max(raio * esc, 1.0);
        } else if (b == 2) {
            x = vnoise(lp / (300.0 * esc) + vec3(0.0, 0.0, emNoiseEvo * 0.1));
        } else {
            x = d / esc;
        }
        if (emNoiseAmp > 0.0) {
            x += (vnoise(lp / (3.0 * max(emNoiseScale, 1.0)) + vec3(emNoiseEvo * 0.1)) - 0.5) * emNoiseAmp;
        }
        c = mix(gradA.rgb, gradB.rgb, clamp(x, 0.0, 1.0));
    } else if (src == 2) {
        c = texture(inputImg, uv).rgb;
    }
    return c * emissionMul;
}

void main() {
    vec2 tam = acResolution;
    vec4 fundo = texture(inputImg, acScreenNorm);
    vec2 px = vec2(acScreenNorm.x * tam.x, (1.0 - acScreenNorm.y) * tam.y);

    // Camera padrao do AE (50 mm): no centro, olhando para +Z, zoom = 1,389 x largura.
    float zoom = tam.x * 1.38889;
    vec3 ro = vec3(tam * 0.5, -zoom);
    vec3 rd = normalize(vec3(px, 0.0) - ro);

    vec3 centro = vec3(position.x * tam.x, (1.0 - position.y) * tam.y, positionZ);
    float esc = max(scale, 1.0) * 0.01;
    vec3 ang = vec3(rotX, rotY, rotZ) * (PI / 180.0);

    // Distorcao Spiral: torce o espaco local em torno de cada eixo, mais forte longe do centro.
    float raioForma = int(shape + 0.5) == 1 ? diameter * 0.5 : length(vec3(width, height, depth)) * 0.5;

    // Faixa do raio dentro da esfera que envolve a forma.
    vec3 oc = ro - centro;
    float R = raioForma * esc * 1.05;
    float b = dot(oc, rd);
    float c = dot(oc, oc) - R * R;
    float h = b * b - c;
    vec3 cor = vec3(0.0);
    vec3 trans = vec3(1.0);
    float dens = 0.0;
    if (h > 0.0) {
        float t0 = max(-b - sqrt(h), 0.0);
        float t1 = -b + sqrt(h);
        int passos = clamp(int(maxSteps + 0.5), 8, 256);
        float dt = (t1 - t0) / float(passos);
        float jit = jitter > 0.5 ? hash3(vec3(acScreenNorm * 911.0, acTime)) : 0.5;
        vec3 absorve = vec3(1.0) - absorption.rgb;
        int nEst = clamp(int(starsCount + 0.5), 0, 16);
        for (int i = 0; i < 256; i++) {
            if (i >= passos) break;
            float t = t0 + (float(i) + jit) * dt;
            vec3 p = ro + rd * t;
            vec3 lp = girar((p - centro) / esc, -ang);
            if (spiralX != 0.0 || spiralY != 0.0 || spiralZ != 0.0) {
                float k = pow(clamp(length(lp) / max(raioForma, 1.0), 0.0, 1.0), spiralExp);
                lp = girar(lp, vec3(spiralX, spiralY, spiralZ) * (PI / 180.0) * k);
            }
            if (mosaicOn > 0.5) {
                vec3 m = floor(lp / max(mosaicSize, 1.0) + 0.5) * max(mosaicSize, 1.0);
                lp = mix(lp, m, mosaicBlend);
            }
            float d = densidade(p, lp);
            if (d <= 0.0005) continue;
            float passo = d * dt * 0.004;
            dens += passo;
            vec3 e = emissao(d, lp, acScreenNorm);
            // estrelas: pontos de luz no volume que acendem a nuvem perto delas
            vec3 luz = vec3(0.0);
            for (int k = 0; k < 16; k++) {
                if (k >= nEst) break;
                float dist = length(lp - posEstrela(k));
                float f = starsIntensity * 0.01 / (1.0 + pow(dist / max(starsFalloff, 1.0), 2.0));
                if (negLight < 0.5) f = max(f, 0.0);
                luz += starsColor.rgb * f;
            }
            cor += trans * (e + luz) * passo;
            trans *= exp(-absorve * passo * 4.0);
            if (max(trans.r, max(trans.g, trans.b)) < 0.005) break;
        }
        // as estrelas aparecem como pontos brilhantes
        for (int k = 0; k < 16; k++) {
            if (k >= nEst) break;
            vec3 sp = centro + girar(posEstrela(k), ang) * esc;
            vec3 v = sp - ro;
            float tp = dot(v, rd);
            float dl = length(v - rd * tp);
            cor += starsColor.rgb * starsIntensity * 0.01 * exp(-dl * dl / 18.0) * trans;
        }
    }

    // Fast Stars: campo de estrelas pequenas no fundo, sem custo de raymarching
    if (fastOn > 0.5) {
        vec2 g = px / (6.0 * max(fastScale, 1.0) * 0.01);
        vec2 cel = floor(g);
        vec2 f = fract(g) - 0.5;
        float hh = hash3(vec3(cel, 7.0 + starsSeed));
        float vis = step(1.0 - fastVis * 0.01 * 0.06, hh);
        vec2 o = vec2(hash3(vec3(cel, 1.0)), hash3(vec3(cel, 2.0))) - 0.5;
        float s = smoothstep(0.12, 0.0, length(f - o * 0.6));
        float it = fastIntensity * 0.01 * mix(1.0, hash3(vec3(cel, 3.0)), fastRand * 0.01);
        cor += fastColor.rgb * s * vis * it * trans;
    }

    float alfa = clamp((1.0 - (trans.r + trans.g + trans.b) / 3.0) * alphaFactor, 0.0, 1.0);
    if (densPreview > 0.5) {
        fragColor = vec4(vec3(clamp(dens, 0.0, 1.0)), 1.0);
        return;
    }
    vec3 atras = fundo.rgb * trans;
    fragColor = vec4(cor + atras, max(fundo.a, alfa));
}
